         "child": "id",
         "op": "eq"
        },
        "node": {
         "table": "box_users",
         "filters": [
          {
           "key": "f_mod",
           "field": "name",
           "op": "eq",
           "value": "Leo Park"
          }
         ],
         "edges": []
        }
       },
       {
        "key": "e_parent",
        "join": {
         "parent": "parent_id",
         "child": "id",
         "op": "eq"
        },
        "node": {
         "table": "box_folders",
         "filters": [],
         "edges": [
          {
           "key": "e_anc",
           "join": {
            "parent": "parent_id",
            "child": "id",
            "op": "eq"
           },
           "closure": "star",
           "node": {
            "table": "box_folders",
            "filters": [
             {
              "key": "f_folder",
              "field": "name",
              "op": "eq",
              "value": "Finance Reports"
             }
            ],
            "edges": []
           }
          }
         ]
        }
       }
      ]
     }
    },
    "explanation": "Matches everything except that it sits in Finance Reports/Drafts, a subfolder the request excludes."
   },
   {
    "witness": "1005",
    "fact": "R:File.modified_by_id",
    "family": "F1",
    "substitute": "File.created_by_id",
    "mutation": {
     "type": "SUB",
     "target": "e_mod",
     "replacement": {
      "key": "e_mod",
      "join": {
       "parent": "created_by_id",
       "child": "id",
       "op": "eq"
      },
      "node": {
       "table": "box_users",
       "filters": [
        {
         "key": "x",
         "field": "name",
         "op": "eq",
         "value": "Leo Park"
        }
       ],
       "edges": []
      }
     }
    },
    "explanation": "Leo Park created it; Maya Chen modified it last."
   },
   {
    "witness": "1006",
    "fact": "A:Folder.name",
    "family": "F8",
    "mutation": {
     "type": "DROP",
     "target": "f_folder"
    },
    "explanation": "Same file facts, but in Finance Archive.",
    "substitute": "a folder whose name shares a word with Finance Reports"
   },
   {
    "witness": "1007",
    "fact": "A:User.name",
    "family": "F8",
    "substitute": "another person named Maya",
    "mutation": {
     "type": "DROP",
     "target": "f_owner"
    },
    "explanation": "Owned by Maya Lopez, not Maya Chen."
   }
