    {"key": "f_email", "field": "email", "op": "contains_ci", "value": "@northwind.example", "fact": "A:User.email"}
   ],
   "edges": [
    {"key": "e_mem", "join": {"parent": "user_id", "child": "user_id", "op": "eq"}, "fact": "R:channel_members",
     "node": {"table": "channel_members", "filters": [], "edges": [
      {"key": "e_chan", "join": {"parent": "channel_id", "child": "channel_id", "op": "eq"},
       "node": {"table": "channels", "filters": [
        {"key": "f_chan", "field": "channel_name", "op": "eq", "value": "launch-week", "fact": "A:Conversation.channel_name"}
       ], "edges": []}}
     ]}}
   ]
  },
  "decoys": [
   {"witness": "@e1", "fact": "A:User.email", "family": "F8",
    "substitute": "an almost-identical address, rosa.delgado@northwind.co",
    "mutation": {"type": "DROP", "target": "f_email"},
    "explanation": "A human named Rosa Delgado in #launch-week, but her address is rosa.delgado@northwind.co, not on the northwind.example domain."},
   {"witness": "@e2", "fact": "A:User.email", "family": "F1",
    "substitute": "the requested identity on the username field: handle @rosa.delgado",
    "mutation": {"type": "DROP", "target": "f_email"},
    "explanation": "Her Slack handle is exactly rosa.delgado, but her address is rosa.delgado@gmail.com, so she fails the @northwind.example address condition."},
   {"witness": "@bot", "fact": "A:User.is_bot", "family": "F0",
    "mutation": {"type": "DROP", "target": "f_bot"},
    "explanation": "A bot account named Rosa Delgado with a @northwind.example address in #launch-week, not a human."}
  ],
  "effect": {"table": "channel_members", "changes": ["insert"], "key": ["channel_id", "user_id"], "field": "user_id"},
  "written": ["channel_members.user_id"]
 },
 "other_references": [
  {"name": "the #platform-launch channel", "target": ["C_PLAT"],
   "query": {"table": "channels", "key": ["channel_id"],
             "filters": [{"key": "f_plat", "field": "channel_name", "op": "eq", "value": "platform-launch", "fact": "A:Conversation.channel_name"}],
             "edges": []}}
 ],
 "write": {"slack": "conversations.invite", "params": {"channel": "C_PLAT", "users": "@target"}},
 "probes": []
}

